using System;
using System.IO;
using System.Linq;
namespace BF4Bots {public static class InstallPathTests {
 public static void Run(){string fixture=Path.Combine(Path.GetTempPath(),"BF4-install-"+Guid.NewGuid().ToString("N"));string steam=Path.Combine(fixture,"SteamLibrary","steamapps","common","Battlefield 4"),vanilla=Path.Combine(fixture,"Original"),missing=Path.Combine(fixture,"Inexistente");Directory.CreateDirectory(steam);Directory.CreateDirectory(vanilla);File.WriteAllText(Path.Combine(vanilla,"bf4.exe"),"");foreach(string file in InstallPath.ClientFiles)File.WriteAllText(Path.Combine(steam,file),"");if(InstallPath.Choose(new[]{missing,vanilla,steam})!=steam)throw new Exception("Não preferiu cliente compatível da Steam.");if(InstallPath.Choose(new[]{missing,vanilla})!=vanilla)throw new Exception("Não reconheceu pasta original da Steam para diagnóstico.");if(InstallPath.Choose(new[]{missing})!=null)throw new Exception("Escolheu pasta inexistente.");if(InstallPath.Missing(vanilla).Length!=3||InstallPath.Missing(steam).Length!=0)throw new Exception("Diagnóstico de arquivos incorreto.");string vdf="\"libraryfolders\" { \"1\" { \"path\" \"D:\\\\SteamLibrary\" } \"2\" { \"path\" \"E:\\\\Jogos Steam\" } }";var paths=InstallPath.Libraries(vdf).ToArray();if(paths.Length!=2||paths[0]!=@"D:\SteamLibrary"||paths[1]!=@"E:\Jogos Steam")throw new Exception("Bibliotecas Steam não foram lidas.");File.WriteAllText(Path.Combine(steam,"config.txt"),"BlazeIP=192.168.1.2");OneClick.PrepareLocal(steam,message=>{throw new Exception("Convidado tentou iniciar serviço local.");});
 }
}}
